var e={lessons:[{id:"portee-cles",title:"La port\xE9e et les cl\xE9s",duration:"5 min",summary:"Ce que sont les cinq lignes de la port\xE9e et \xE0 quoi servent les cl\xE9s de Sol et de Fa."},{id:"notes-de-musique",title:"Les notes de musique",duration:"4 min",summary:"Les sept noms de notes, les octaves, et comment elles se r\xE9p\xE8tent \xE0 l'infini."},{id:"figures-de-note",title:"Les figures de note et les dur\xE9es",duration:"6 min",summary:"Ronde, blanche, noire, croche : comment la forme d'une note indique sa dur\xE9e."},{id:"alterations",title:"Les alt\xE9rations : di\xE8se, b\xE9mol, b\xE9carre",duration:"4 min",summary:"Comment hausser ou baisser une note d'un demi-ton, et ce qu'est l'armure."},{id:"gammes-majeures",title:"Les gammes majeures",duration:"6 min",summary:"La recette T-T-ST-T-T-T-ST qui construit toutes les gammes majeures, et le r\xF4le de l'armure."},{id:"gammes-mineures",title:"Les gammes mineures",duration:"6 min",summary:"Trois versions de la gamme mineure (naturelle, harmonique, m\xE9lodique) et son lien avec la gamme majeure relative."},{id:"intervalles",title:"Les intervalles",duration:"5 min",summary:"Mesurer la distance entre deux notes, et reconna\xEEtre les intervalles les plus courants."},{id:"mesure-temps",title:"La mesure et les temps",duration:"5 min",summary:"Lire un chiffrage de mesure, distinguer mesures binaires et ternaires, et rep\xE9rer les temps forts."},{id:"cercle-quintes",title:"Le cercle des quintes",duration:"5 min",summary:"Une carte de toutes les tonalit\xE9s majeures, rang\xE9es par nombre croissant de di\xE8ses ou de b\xE9mols."},{id:"nuances-tempo",title:"Les nuances et le tempo",duration:"5 min",summary:"Lire les indications d'intensit\xE9 (nuances) et de vitesse (tempo) qui accompagnent une partition."},{id:"accords-base",title:"Les accords de base",duration:"5 min",summary:"Empiler des tierces pour former un accord parfait majeur ou mineur."},{id:"degres-gamme",title:"Les degr\xE9s de la gamme",duration:"5 min",summary:"Le nom et le r\xF4le de chaque note d'une gamme : tonique, dominante, sensible..."},{id:"silences-liaisons",title:"Silences, liaisons, points et triolets",duration:"6 min",summary:"Ce que veut dire une pause, un point apr\xE8s une note, un trait courbe ou un petit 3 au-dessus d'un groupe."},{id:"signes-reprise",title:"Les signes de reprise",duration:"5 min",summary:"Barres de reprise, premi\xE8re et deuxi\xE8me fins, D.C., D.S., Fine et Coda : comment une partition \xE9vite de tout r\xE9\xE9crire."},{id:"modes-grecs",title:"Les modes grecs",duration:"6 min",summary:"Sept couleurs diff\xE9rentes obtenues en jouant les touches blanches \xE0 partir d'une note diff\xE9rente \xE0 chaque fois."},{id:"accords-septieme",title:"Les accords de septi\xE8me",duration:"5 min",summary:"Empiler une troisi\xE8me tierce sur une triade pour obtenir un accord de septi\xE8me \u2014 et comprendre pourquoi le septi\xE8me de dominante est si central."},{id:"transposition",title:"La transposition",duration:"4 min",summary:"D\xE9placer un morceau dans une autre tonalit\xE9 en conservant exactement les m\xEAmes intervalles entre les notes."},{id:"harmonisation-degres",title:"Harmoniser les degr\xE9s de la gamme",duration:"6 min",summary:"Un accord diff\xE9rent \u2014 majeur, mineur ou diminu\xE9 \u2014 na\xEEt naturellement sur chacun des sept degr\xE9s d'une gamme majeure."},{id:"substitution-accords",title:"Les substitutions d'accords",duration:"5 min",summary:"Remplacer un accord par un autre qui partage sa fonction ou ses notes, sans d\xE9naturer l'harmonie."},{id:"basse-chiffree",title:"La basse chiffr\xE9e",duration:"5 min",summary:"Une notation baroque compacte : la ligne de basse, accompagn\xE9e de chiffres qui indiquent l'accord \xE0 construire au-dessus."},{id:"cadences",title:"Les cadences",duration:"5 min",summary:"Quatre fa\xE7ons de conclure \u2014 ou de suspendre \u2014 une phrase musicale avec un encha\xEEnement de deux accords."},{id:"ornements",title:"Les ornements",duration:"5 min",summary:"Trille, appoggiature, mordant : de petites notes ajout\xE9es qui d\xE9corent une m\xE9lodie sans en changer le fond."},{id:"chromatisme",title:"Le chromatisme et les notes de passage",duration:"5 min",summary:"La gamme chromatique (les douze demi-tons), et comment de courtes notes \xE9trang\xE8res \xE0 l'accord relient les notes d'une m\xE9lodie."},{id:"forme-musicale",title:"La forme musicale",duration:"5 min",summary:"Comment un morceau s'organise en grandes sections : forme binaire, ternaire, ou th\xE8me et variations."},{id:"articulations",title:"Les articulations",duration:"4 min",summary:"Staccato, legato, tenuto, accent : comment une m\xEAme note peut \xEAtre jou\xE9e de fa\xE7ons tr\xE8s diff\xE9rentes."}],games:[{id:"clef-sol",title:"Lecture de notes \u2014 Cl\xE9 de Sol",summary:"Identifie le plus vite possible les notes sur la port\xE9e en cl\xE9 de Sol."},{id:"clef-fa",title:"Lecture de notes \u2014 Cl\xE9 de Fa",summary:"M\xEAme principe, pour les sons graves : main gauche, violoncelle, basson..."},{id:"rythme",title:"Jeu de rythme",summary:"\xC9coute la pulsation et tape en rythme au bon moment."},{id:"tonalites",title:"Jeu des tonalit\xE9s",summary:"Devine la tonalit\xE9 majeure \xE0 partir de son armure (di\xE8ses ou b\xE9mols)."},{id:"intervalles",title:"Jeu des intervalles",summary:"Identifie la distance entre deux notes, de la seconde \xE0 l'octave."},{id:"accords",title:"Jeu des accords",summary:"Majeur, mineur, ou l'une des trois septi\xE8mes : reconnais l'accord affich\xE9."},{id:"durees-silences",title:"Jeu des dur\xE9es et silences",summary:"Ronde, soupir, double-croche... identifie chaque figure et son silence."},{id:"degres",title:"Jeu des degr\xE9s",summary:"Retrouve le nom du degr\xE9 (tonique, dominante, sensible...) d'une note en Do majeur."}],tools:[{id:"metronome",title:"M\xE9tronome",summary:"Garde le tempo, avec accentuation du premier temps."},{id:"accordeur",title:"Accordeur",summary:"Utilise le micro pour v\xE9rifier la justesse d'un instrument."},{id:"piano",title:"Piano virtuel",summary:"Deux octaves jouables \xE0 la souris ou au clavier d'ordinateur."}]};export{e as a};
